#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""
_update9.py

Skrypt wprowadzajacy SLOWNIK TAGOW PRZECIWWSKAZAN (ContraindicationTag) -
fundament pod automatyczne ostrzezenia przy ukladaniu planow treningowych.

WYMAGA wczesniej zastosowanych: _update6.py, _update7.py, _update8.py
(modul 'clients' musi juz istniec).

CO DODAJE:
  - Nowy model ContraindicationTag w aplikacji 'exercises' (wspolny slownik)
  - Pole M2M Exercise.contraindication_tags - tagowanie cwiczen w katalogu
  - Pole M2M Dog.health_tags - tagowanie profilu zdrowotnego psa
  - Metoda Dog.get_shared_tags(exercise) - zwraca wspolne tagi (do ostrzezen)
  - Panel admina: ContraindicationTagAdmin, filtrowanie po tagach
  - Formularze: checkbox listy tagow w formularzu cwiczenia i psa
  - Widoki szczegolow: wyswietlanie przypisanych tagow (badge)
  - Management command 'tag_exercises' - tworzy 9 startowych tagow i
    AUTOMATYCZNIE przypisuje je do istniejacych cwiczen na podstawie
    analizy nazwy/opisu/grup miesniowych (mozliwa reczna korekta w /admin/)
    Komenda jest IDEMPOTENTNA - mozna ja uruchamiac wielokrotnie.

STARTOWY SLOWNIK TAGOW:
  - Wysokie obciazenie stawow
  - Odpowiednie przy rehabilitacji stawow
  - Konczyny miedniczne (KKM)
  - Konczyny przednie (KKP)
  - Kregoslup / grzbiet
  - Skoki / dynamika
  - Szyja
  - Klus / bieg
  - Balans / niestabilne powierzchnie

Uruchom z GLOWNEGO folderu projektu (tam gdzie jest manage.py):
    python _update9.py

PO URUCHOMIENIU WYMAGANE (W TEJ KOLEJNOSCI):
    python manage.py makemigrations exercises
    python manage.py makemigrations clients
    python manage.py migrate
    python manage.py tag_exercises
"""

import os
import shutil
import sys
import datetime

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
BACKUP_DIR = os.path.join(BASE_DIR, "_update9_backup_" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S"))

FILES = {}

FILES['exercises/models.py'] = 'import re\nfrom django.db import models\n\n\nclass MuscleGroup(models.Model):\n    name = models.CharField(max_length=100, unique=True)\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name = "Grupa miesniowa"\n        verbose_name_plural = "Grupy miesniowe"\n\n    def __str__(self):\n        return self.name\n\n\nclass Equipment(models.Model):\n    name = models.CharField(max_length=100, unique=True)\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name = "Sprzet"\n        verbose_name_plural = "Sprzet"\n\n    def __str__(self):\n        return self.name\n\n\nclass ContraindicationTag(models.Model):\n    """Slownik tagow przeciwwskazan - wspolny dla Exercise (co moze byc\n    ryzykowne w cwiczeniu) i Dog (jakie obszary zdrowotne wymagaja uwagi\n    u konkretnego psa). Przeciecie tagow = automatyczne ostrzezenie."""\n    name = models.CharField(max_length=100, unique=True, verbose_name="Nazwa tagu")\n    description = models.CharField(max_length=255, blank=True, verbose_name="Opis (opcjonalnie)")\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name = "Tag przeciwwskazania"\n        verbose_name_plural = "Tagi przeciwwskazan"\n\n    def __str__(self):\n        return self.name\n\n\nclass Exercise(models.Model):\n    DIFFICULTY_CHOICES = [\n        (\'easy\', \'Latwy\'),\n        (\'medium\', \'Sredni\'),\n        (\'hard\', \'Trudny\'),\n    ]\n\n    name = models.CharField(max_length=200, verbose_name="Nazwa")\n    description = models.TextField(verbose_name="Opis")\n    video_url = models.URLField(blank=True, null=True, verbose_name="Link do video", help_text="Link np. do YouTube")\n    muscle_groups = models.ManyToManyField(MuscleGroup, related_name=\'exercises\', verbose_name="Grupy miesniowe")\n    difficulty = models.CharField(max_length=10, choices=DIFFICULTY_CHOICES, verbose_name="Poziom trudnosci")\n    equipment = models.ManyToManyField(Equipment, blank=True, related_name=\'exercises\', verbose_name="Potrzebny sprzet")\n    contraindications = models.TextField(blank=True, verbose_name="Przeciwwskazania")\n    contraindication_tags = models.ManyToManyField(\n        ContraindicationTag, blank=True, related_name=\'exercises\',\n        verbose_name="Tagi przeciwwskazan",\n        help_text="Uzywane do automatycznych ostrzezen przy ukladaniu planu dla psa z podobnymi tagami zdrowotnymi."\n    )\n\n    parent_exercise = models.ForeignKey(\n        \'self\', null=True, blank=True,\n        on_delete=models.SET_NULL,\n        related_name=\'variants\',\n        verbose_name="Wariant cwiczenia"\n    )\n    variant_name = models.CharField(\n        max_length=100, blank=True,\n        verbose_name="Nazwa wariantu",\n        help_text=\'np. "Zaawansowany", "Z pilka", "Dla szczeniaka"\'\n    )\n\n    is_active = models.BooleanField(default=True, verbose_name="Aktywne")\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = [\'-created_at\']\n        verbose_name = "Cwiczenie"\n        verbose_name_plural = "Cwiczenia"\n\n    def __str__(self):\n        return self.name\n\n    def get_youtube_embed_url(self):\n        """Zwraca URL do embedowania video YouTube, albo None jesli to nie YouTube/niepoprawny link"""\n        if not self.video_url:\n            return None\n\n        patterns = [\n            r\'(?:youtube\\.com\\/watch\\?v=)([^&\\n?#]+)\',\n            r\'(?:youtu\\.be\\/)([^&\\n?#]+)\',\n            r\'(?:youtube\\.com\\/embed\\/)([^&\\n?#]+)\',\n        ]\n        for pattern in patterns:\n            match = re.search(pattern, self.video_url)\n            if match:\n                return f\'https://www.youtube.com/embed/{match.group(1)}\'\n        return None\n\n    def active_variants(self):\n        """Lista aktywnych wariantow tego cwiczenia (jesli to cwiczenie \'glowne\')"""\n        return self.variants.filter(is_active=True).order_by(\'created_at\')\n\n    def get_root(self):\n        """Zwraca cwiczenie \'glowne\' - jesli to wariant, zwraca jego rodzica; jesli samo jest glowne, zwraca siebie"""\n        return self.parent_exercise if self.parent_exercise else self\n\n    def get_cover_image(self):\n        """Zwraca zdjecie oznaczone jako okladka, albo pierwsze dostepne zdjecie (wg kolejnosci)"""\n        cover = self.images.filter(is_cover=True).first()\n        return cover or self.images.order_by(\'order\', \'pk\').first()\n\n\nclass ExerciseImage(models.Model):\n    exercise = models.ForeignKey(Exercise, related_name=\'images\', on_delete=models.CASCADE)\n    image = models.ImageField(upload_to=\'exercises/\')\n    is_cover = models.BooleanField(default=False, verbose_name="Zdjecie okladkowe")\n    order = models.PositiveIntegerField(default=0, verbose_name="Kolejnosc")\n\n    MAX_DIMENSION = 1600\n\n    class Meta:\n        ordering = [\'order\', \'pk\']\n        verbose_name = "Zdjecie cwiczenia"\n        verbose_name_plural = "Zdjecia cwiczen"\n\n    def __str__(self):\n        return f"Zdjecie dla {self.exercise.name}"\n\n    def save(self, *args, **kwargs):\n        super().save(*args, **kwargs)\n        self._resize_if_needed()\n\n    def _resize_if_needed(self):\n        """Automatycznie skaluje i kompresuje zdjecie, jesli jest wieksze niz MAX_DIMENSION.\n        Dzialanie \'pod maska\' - bez wplywu na UI, oszczedza miejsce i czas wczytywania."""\n        try:\n            from PIL import Image as PILImage\n            if not self.image or not self.image.name:\n                return\n            path = self.image.path\n            with PILImage.open(path) as img:\n                width, height = img.size\n                if width <= self.MAX_DIMENSION and height <= self.MAX_DIMENSION:\n                    return\n\n                img = img.convert(\'RGB\') if img.mode in (\'RGBA\', \'P\') else img\n                img.thumbnail((self.MAX_DIMENSION, self.MAX_DIMENSION), PILImage.LANCZOS)\n\n                save_kwargs = {\'optimize\': True}\n                fmt = (img.format or \'JPEG\')\n                if path.lower().endswith((\'.jpg\', \'.jpeg\')):\n                    save_kwargs[\'quality\'] = 85\n                    fmt = \'JPEG\'\n                img.save(path, format=fmt, **save_kwargs)\n        except Exception:\n            pass\n'
FILES['exercises/admin.py'] = 'from django.contrib import admin\nfrom .models import MuscleGroup, Equipment, Exercise, ExerciseImage, ContraindicationTag\n\n\nclass ExerciseImageInline(admin.TabularInline):\n    model = ExerciseImage\n    extra = 1\n    max_num = 5\n    fields = (\'image\', \'is_cover\', \'order\')\n\n\n@admin.register(MuscleGroup)\nclass MuscleGroupAdmin(admin.ModelAdmin):\n    list_display = (\'name\',)\n    search_fields = (\'name\',)\n\n\n@admin.register(Equipment)\nclass EquipmentAdmin(admin.ModelAdmin):\n    list_display = (\'name\',)\n    search_fields = (\'name\',)\n\n\n@admin.register(ContraindicationTag)\nclass ContraindicationTagAdmin(admin.ModelAdmin):\n    list_display = (\'name\', \'description\')\n    search_fields = (\'name\', \'description\')\n\n\n@admin.register(Exercise)\nclass ExerciseAdmin(admin.ModelAdmin):\n    list_display = (\'name\', \'variant_name\', \'parent_exercise\', \'difficulty\', \'is_active\', \'created_at\')\n    list_filter = (\'difficulty\', \'is_active\', \'muscle_groups\', \'equipment\', \'contraindication_tags\')\n    search_fields = (\'name\', \'description\', \'variant_name\')\n    filter_horizontal = (\'muscle_groups\', \'equipment\', \'contraindication_tags\')\n    inlines = [ExerciseImageInline]\n    actions = [\'make_active\', \'make_archived\']\n    list_per_page = 50\n    date_hierarchy = \'created_at\'\n\n    def make_active(self, request, queryset):\n        updated = queryset.update(is_active=True)\n        self.message_user(request, f"Przywrocono {updated} cwiczen (ustawiono jako aktywne).")\n    make_active.short_description = "Przywroc zaznaczone (ustaw jako aktywne)"\n\n    def make_archived(self, request, queryset):\n        updated = queryset.update(is_active=False)\n        self.message_user(request, f"Zarchiwizowano {updated} cwiczen.")\n    make_archived.short_description = "Zarchiwizuj zaznaczone"\n'
FILES['exercises/forms.py'] = 'from django import forms\nfrom django.core.exceptions import ValidationError\nfrom .models import MuscleGroup, Equipment, Exercise, ContraindicationTag\n\nMAX_IMAGE_SIZE_MB = 5\nMAX_IMAGES_PER_EXERCISE = 5\n\n\nclass MuscleGroupForm(forms.ModelForm):\n    class Meta:\n        model = MuscleGroup\n        fields = [\'name\']\n        widgets = {\n            \'name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. Core, Tylne lapy\'}),\n        }\n\n\nclass EquipmentForm(forms.ModelForm):\n    class Meta:\n        model = Equipment\n        fields = [\'name\']\n        widgets = {\n            \'name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. Pilka, Step\'}),\n        }\n\n\nclass ContraindicationTagForm(forms.ModelForm):\n    class Meta:\n        model = ContraindicationTag\n        fields = [\'name\', \'description\']\n        widgets = {\n            \'name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. Wysokie obciazenie stawow\'}),\n            \'description\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'Opcjonalny opis tagu\'}),\n        }\n\n\nclass ExerciseForm(forms.ModelForm):\n    class Meta:\n        model = Exercise\n        fields = [\n            \'name\', \'description\', \'video_url\',\n            \'muscle_groups\', \'difficulty\', \'equipment\',\n            \'contraindications\', \'contraindication_tags\',\n            \'parent_exercise\', \'variant_name\',\n        ]\n        widgets = {\n            \'name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'Nazwa cwiczenia\'}),\n            \'description\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 4, \'placeholder\': \'Opisz jak wykonac cwiczenie...\'}),\n            \'video_url\': forms.URLInput(attrs={\'class\': \'form-control\', \'placeholder\': \'https://youtube.com/watch?v=...\'}),\n            \'muscle_groups\': forms.CheckboxSelectMultiple(),\n            \'difficulty\': forms.Select(attrs={\'class\': \'form-select\'}),\n            \'equipment\': forms.CheckboxSelectMultiple(),\n            \'contraindications\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 3, \'placeholder\': \'Np. nie dla psow z dysplazja stawow...\'}),\n            \'contraindication_tags\': forms.CheckboxSelectMultiple(),\n            \'parent_exercise\': forms.Select(attrs={\'class\': \'form-select\'}),\n            \'variant_name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. Zaawansowany, Z pilka, Dla szczeniaka\'}),\n        }\n\n    def __init__(self, *args, **kwargs):\n        super().__init__(*args, **kwargs)\n        qs = Exercise.objects.filter(parent_exercise__isnull=True, is_active=True)\n        if self.instance and self.instance.pk:\n            exclude_ids = [self.instance.pk] + list(self.instance.variants.values_list(\'pk\', flat=True))\n            qs = qs.exclude(pk__in=exclude_ids)\n        self.fields[\'parent_exercise\'].queryset = qs\n        self.fields[\'parent_exercise\'].required = False\n        self.fields[\'parent_exercise\'].empty_label = "- Samodzielne cwiczenie (nie wariant) -"\n        self.fields[\'variant_name\'].required = False\n        self.fields[\'contraindication_tags\'].required = False\n\n    def clean_name(self):\n        name = self.cleaned_data.get(\'name\', \'\').strip()\n        if len(name) < 3:\n            raise ValidationError(\'Nazwa musi miec przynajmniej 3 znaki.\')\n        return name\n\n    def clean_description(self):\n        description = self.cleaned_data.get(\'description\', \'\').strip()\n        if len(description) < 10:\n            raise ValidationError(\'Opis musi miec przynajmniej 10 znakow - pomoz trenerowi zrozumiec cwiczenie.\')\n        return description\n\n    def clean_muscle_groups(self):\n        groups = self.cleaned_data.get(\'muscle_groups\')\n        if not groups:\n            raise ValidationError(\'Wybierz przynajmniej jedna grupe miesniowa.\')\n        return groups\n\n    def clean_video_url(self):\n        url = self.cleaned_data.get(\'video_url\')\n        if url:\n            allowed_domains = [\'youtube.com\', \'youtu.be\', \'vimeo.com\']\n            if not any(domain in url for domain in allowed_domains):\n                raise ValidationError(\'Link do video musi prowadzic do YouTube lub Vimeo.\')\n        return url\n\n    def clean(self):\n        cleaned = super().clean()\n        parent = cleaned.get(\'parent_exercise\')\n        variant_name = cleaned.get(\'variant_name\', \'\').strip()\n        if parent and not variant_name:\n            self.add_error(\'variant_name\', \'Podaj nazwe wariantu, np. "Zaawansowany" albo "Z pilka".\')\n        return cleaned\n\n\nclass MultipleFileInput(forms.ClearableFileInput):\n    allow_multiple_selected = True\n\n\nclass MultipleFileField(forms.FileField):\n    def __init__(self, *args, **kwargs):\n        kwargs.setdefault(\'widget\', MultipleFileInput())\n        super().__init__(*args, **kwargs)\n\n    def clean(self, data, initial=None):\n        single_file_clean = super().clean\n        if isinstance(data, (list, tuple)):\n            result = [single_file_clean(d, initial) for d in data]\n        else:\n            result = single_file_clean(data, initial)\n        return result\n\n\nclass ExerciseImageUploadForm(forms.Form):\n    """Formularz uploadu zdjec. Przyjmuje \'existing_count\' - liczbe zdjec,\n    ktore dane cwiczenie (wariant) juz posiada - zeby wyliczyc limit\n    MAX_IMAGES_PER_EXERCISE lacznie (stare + nowe)."""\n\n    images = MultipleFileField(\n        required=False,\n        widget=MultipleFileInput(attrs={\'class\': \'form-control\', \'multiple\': True})\n    )\n\n    def __init__(self, *args, existing_count=0, **kwargs):\n        self.existing_count = existing_count\n        super().__init__(*args, **kwargs)\n\n    def clean_images(self):\n        images = self.cleaned_data.get(\'images\')\n        if not images:\n            return images\n\n        if not isinstance(images, list):\n            images = [images]\n\n        total_after = self.existing_count + len(images)\n        if total_after > MAX_IMAGES_PER_EXERCISE:\n            allowed_now = max(MAX_IMAGES_PER_EXERCISE - self.existing_count, 0)\n            raise ValidationError(\n                f\'Ten wariant cwiczenia moze miec maksymalnie {MAX_IMAGES_PER_EXERCISE} zdjec. \'\n                f\'Masz juz {self.existing_count}, mozesz dodac jeszcze {allowed_now}.\'\n            )\n\n        for img in images:\n            if img.size > MAX_IMAGE_SIZE_MB * 1024 * 1024:\n                raise ValidationError(f\'Plik "{img.name}" jest za duzy (max {MAX_IMAGE_SIZE_MB}MB).\')\n            if not img.content_type.startswith(\'image/\'):\n                raise ValidationError(f\'Plik "{img.name}" nie jest obrazem.\')\n\n        return images\n'
FILES['exercises/templates/exercises/exercise_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }}</h1>\n\n<div class="form-card">\n    <form method="post" enctype="multipart/form-data">\n        {% csrf_token %}\n\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        <div class="mb-3">\n            <label class="form-label">Nazwa</label>\n            {{ form.name }}\n            {% if form.name.errors %}<div class="invalid-feedback-custom">{{ form.name.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Opis</label>\n            {{ form.description }}\n            {% if form.description.errors %}<div class="invalid-feedback-custom">{{ form.description.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Link do video (YouTube/Vimeo, opcjonalnie)</label>\n            {{ form.video_url }}\n            {% if form.video_url.errors %}<div class="invalid-feedback-custom">{{ form.video_url.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Poziom trudnosci</label>\n            {{ form.difficulty }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Grupy miesniowe</label>\n            <div class="checkbox-group">\n                {{ form.muscle_groups }}\n            </div>\n            {% if form.muscle_groups.errors %}<div class="invalid-feedback-custom">{{ form.muscle_groups.errors|first }}</div>{% endif %}\n            <small class="text-muted">Nie widzisz potrzebnej grupy? <a href="{% url \'muscle_group_create\' %}" target="_blank">Dodaj nowa</a></small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Potrzebny sprzet</label>\n            <div class="checkbox-group">\n                {{ form.equipment }}\n            </div>\n            <small class="text-muted">Nie widzisz potrzebnego sprzetu? <a href="{% url \'equipment_create\' %}" target="_blank">Dodaj nowy</a></small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Przeciwwskazania - opis slowny (opcjonalnie)</label>\n            {{ form.contraindications }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label"><i class="bi bi-tags"></i> Tagi przeciwwskazan (opcjonalnie)</label>\n            <div class="checkbox-group">\n                {{ form.contraindication_tags }}\n            </div>\n            <small class="text-muted">\n                Uzywane do automatycznych ostrzezen - jesli pies ma przypisany ten sam tag zdrowotny,\n                trener zobaczy ostrzezenie przy tym cwiczeniu.\n            </small>\n        </div>\n\n        <hr class="my-4">\n\n        <h5 class="mb-3"><i class="bi bi-diagram-2"></i> Warianty</h5>\n\n        <div class="mb-3">\n            <label class="form-label">To cwiczenie jest wariantem innego cwiczenia</label>\n            {{ form.parent_exercise }}\n            <small class="text-muted">Wybierz, jesli to np. trudniejsza/latwiejsza wersja istniejacego cwiczenia</small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Nazwa wariantu (wymagana, jesli wybrano powyzej)</label>\n            {{ form.variant_name }}\n            {% if form.variant_name.errors %}<div class="invalid-feedback-custom">{{ form.variant_name.errors|first }}</div>{% endif %}\n        </div>\n\n        <hr class="my-4">\n\n        <div class="mb-3">\n            <label class="form-label"><i class="bi bi-images"></i> Dodaj zdjecia</label>\n            {{ image_form.images }}\n            {% if image_form.images.errors %}<div class="invalid-feedback-custom">{{ image_form.images.errors|first }}</div>{% endif %}\n            <small class="text-muted">\n                Limit: <strong>{{ existing_images_count }} / 5</strong> zdjec dla tego wariantu.\n                Max 5MB na plik. Duze zdjecia zostana automatycznie zmniejszone.\n            </small>\n        </div>\n\n        {% if exercise and exercise.images.all %}\n            <div class="mb-3">\n                <label class="form-label">\n                    Istniejace zdjecia - przeciagnij aby zmienic kolejnosc, wybierz okladke <i class="bi bi-star-fill" style="color:#D4AF37;"></i>\n                </label>\n                <div class="row" id="existing-images-sortable" data-reorder-url="{% url \'exercise_image_reorder\' exercise.pk %}">\n                    {% for img in exercise.images.all %}\n                    <div class="col-3 mb-2 text-center sortable-image-item" data-id="{{ img.pk }}">\n                        <div class="cover-select-wrapper">\n                            <img src="{{ img.image.url }}" class="img-fluid rounded mb-1" style="aspect-ratio: 1; object-fit: cover;" alt="Zdjecie">\n                            <label class="cover-radio-label">\n                                <input type="radio" name="cover_image" value="{{ img.pk }}" {% if img.is_cover %}checked{% endif %}>\n                                Okladka\n                            </label>\n                        </div>\n                        <span class="drag-handle-hint"><i class="bi bi-arrows-move"></i> przeciagnij</span>\n                        <form method="post" action="{% url \'exercise_image_delete\' img.pk %}" class="image-delete-form mt-1">\n                            {% csrf_token %}\n                            <button type="submit" class="btn btn-sm btn-outline-danger w-100">\n                                <i class="bi bi-trash"></i>\n                            </button>\n                        </form>\n                    </div>\n                    {% endfor %}\n                </div>\n            </div>\n        {% endif %}\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            <a href="{% url \'exercise_list\' %}" class="btn btn-secondary">Anuluj</a>\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['clients/models.py'] = 'from datetime import date\nfrom django.conf import settings\nfrom django.db import models\n\n\nclass Owner(models.Model):\n    first_name = models.CharField(max_length=100, verbose_name="Imie")\n    last_name = models.CharField(max_length=100, verbose_name="Nazwisko")\n    phone = models.CharField(max_length=30, verbose_name="Telefon")\n    email = models.EmailField(blank=True, verbose_name="Email")\n    address = models.CharField(max_length=255, blank=True, verbose_name="Adres")\n    notes = models.TextField(blank=True, verbose_name="Notatki")\n    is_active = models.BooleanField(default=True, verbose_name="Aktywny")\n\n    secondary_contact_name = models.CharField(\n        max_length=100, blank=True, verbose_name="Kontakt zastepczy - imie i nazwisko"\n    )\n    secondary_contact_phone = models.CharField(\n        max_length=30, blank=True, verbose_name="Kontakt zastepczy - telefon"\n    )\n\n    rodo_consent = models.BooleanField(\n        default=False, verbose_name="Zgoda na przetwarzanie danych osobowych (RODO)"\n    )\n    rodo_consent_date = models.DateField(\n        null=True, blank=True, verbose_name="Data udzielenia zgody RODO"\n    )\n    photo_consent = models.BooleanField(\n        default=False, verbose_name="Zgoda na wykorzystanie zdjec psa (np. social media)"\n    )\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = [\'last_name\', \'first_name\']\n        verbose_name = "Wlasciciel"\n        verbose_name_plural = "Wlasciciele"\n\n    def __str__(self):\n        return self.full_name\n\n    @property\n    def full_name(self):\n        return f"{self.first_name} {self.last_name}"\n\n    def active_dogs(self):\n        return self.dogs.filter(is_active=True)\n\n    def save(self, *args, **kwargs):\n        if self.rodo_consent and not self.rodo_consent_date:\n            self.rodo_consent_date = date.today()\n        if not self.rodo_consent:\n            self.rodo_consent_date = None\n        super().save(*args, **kwargs)\n\n\nclass Dog(models.Model):\n    SEX_MALE = \'M\'\n    SEX_FEMALE = \'F\'\n    SEX_CHOICES = [\n        (SEX_MALE, \'Pies (samiec)\'),\n        (SEX_FEMALE, \'Suczka (samica)\'),\n    ]\n\n    STATUS_ACTIVE = \'active\'\n    STATUS_PAUSED = \'paused\'\n    TRAINING_STATUS_CHOICES = [\n        (STATUS_ACTIVE, \'Aktywny\'),\n        (STATUS_PAUSED, \'Wstrzymany (tymczasowo)\'),\n    ]\n\n    owner = models.ForeignKey(\n        Owner, related_name=\'dogs\', on_delete=models.CASCADE, verbose_name="Wlasciciel"\n    )\n    name = models.CharField(max_length=100, verbose_name="Imie psa")\n    breed = models.CharField(max_length=100, blank=True, verbose_name="Rasa")\n    sex = models.CharField(max_length=1, choices=SEX_CHOICES, blank=True, verbose_name="Plec")\n    birth_date = models.DateField(null=True, blank=True, verbose_name="Data urodzenia")\n    weight_kg = models.DecimalField(\n        max_digits=5, decimal_places=2, null=True, blank=True, verbose_name="Waga (kg)"\n    )\n    health_notes = models.TextField(blank=True, verbose_name="Informacje zdrowotne / przeciwwskazania")\n    health_tags = models.ManyToManyField(\n        \'exercises.ContraindicationTag\', blank=True, related_name=\'dogs\',\n        verbose_name="Tagi zdrowotne (przeciwwskazania)",\n        help_text="Uzywane do automatycznych ostrzezen przy ukladaniu planu treningowego."\n    )\n    trainer_notes = models.TextField(blank=True, verbose_name="Notatki trenera")\n    photo = models.ImageField(upload_to=\'dogs/\', blank=True, null=True, verbose_name="Zdjecie")\n\n    training_status = models.CharField(\n        max_length=10, choices=TRAINING_STATUS_CHOICES, default=STATUS_ACTIVE,\n        verbose_name="Status treningowy"\n    )\n    is_active = models.BooleanField(default=True, verbose_name="Aktywny (archiwizacja)")\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    MAX_DIMENSION = 1600\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name = "Pies"\n        verbose_name_plural = "Psy"\n\n    def __str__(self):\n        return self.name\n\n    def get_age_display(self):\n        if not self.birth_date:\n            return None\n        today = date.today()\n        if self.birth_date > today:\n            return None\n\n        years = today.year - self.birth_date.year - (\n            (today.month, today.day) < (self.birth_date.month, self.birth_date.day)\n        )\n        months = (today.year - self.birth_date.year) * 12 + (today.month - self.birth_date.month)\n        if today.day < self.birth_date.day:\n            months -= 1\n\n        if years < 1:\n            m = max(months, 0)\n            if m == 0:\n                return "poniżej miesiąca"\n            elif m == 1:\n                return f"{m} miesiąc"\n            elif 2 <= m <= 4:\n                return f"{m} miesiące"\n            else:\n                return f"{m} miesięcy"\n        else:\n            y = years\n            if y == 1:\n                return f"{y} rok"\n            elif 2 <= (y % 10) <= 4 and not (11 <= (y % 100) <= 14):\n                return f"{y} lata"\n            else:\n                return f"{y} lat"\n\n    def get_shared_tags(self, exercise):\n        """Zwraca liste tagow wspolnych dla tego psa i podanego cwiczenia\n        (Exercise z modulu \'exercises\') - uzywane do ostrzezen przy\n        dodawaniu cwiczenia do planu treningowego."""\n        dog_tag_ids = set(self.health_tags.values_list(\'pk\', flat=True))\n        if not dog_tag_ids:\n            return []\n        exercise_tags = exercise.contraindication_tags.filter(pk__in=dog_tag_ids)\n        return list(exercise_tags)\n\n    def save(self, *args, **kwargs):\n        super().save(*args, **kwargs)\n        self._resize_photo_if_needed()\n\n    def _resize_photo_if_needed(self):\n        try:\n            from PIL import Image as PILImage\n            if not self.photo or not self.photo.name:\n                return\n            path = self.photo.path\n            with PILImage.open(path) as img:\n                width, height = img.size\n                if width <= self.MAX_DIMENSION and height <= self.MAX_DIMENSION:\n                    return\n                img = img.convert(\'RGB\') if img.mode in (\'RGBA\', \'P\') else img\n                img.thumbnail((self.MAX_DIMENSION, self.MAX_DIMENSION), PILImage.LANCZOS)\n                save_kwargs = {\'optimize\': True}\n                fmt = (img.format or \'JPEG\')\n                if path.lower().endswith((\'.jpg\', \'.jpeg\')):\n                    save_kwargs[\'quality\'] = 85\n                    fmt = \'JPEG\'\n                img.save(path, format=fmt, **save_kwargs)\n        except Exception:\n            pass\n\n\nclass AuditLog(models.Model):\n    """Dziennik zmian (audit log) dla modulu Klienci - zapisuje KTO i KIEDY\n    wykonal jaka akcje na kliencie lub psie."""\n\n    ACTION_CREATED = \'created\'\n    ACTION_UPDATED = \'updated\'\n    ACTION_ARCHIVED = \'archived\'\n    ACTION_RESTORED = \'restored\'\n    ACTION_DELETED_PERMANENT = \'deleted_permanent\'\n    ACTION_STATUS_TOGGLED = \'status_toggled\'\n    ACTION_CHOICES = [\n        (ACTION_CREATED, \'Dodano\'),\n        (ACTION_UPDATED, \'Zaktualizowano\'),\n        (ACTION_ARCHIVED, \'Zarchiwizowano\'),\n        (ACTION_RESTORED, \'Przywrocono\'),\n        (ACTION_DELETED_PERMANENT, \'Usunieto na zawsze\'),\n        (ACTION_STATUS_TOGGLED, \'Zmieniono status treningowy\'),\n    ]\n\n    TARGET_OWNER = \'owner\'\n    TARGET_DOG = \'dog\'\n    TARGET_CHOICES = [\n        (TARGET_OWNER, \'Wlasciciel\'),\n        (TARGET_DOG, \'Pies\'),\n    ]\n\n    timestamp = models.DateTimeField(auto_now_add=True, verbose_name="Data i czas")\n    user = models.ForeignKey(\n        settings.AUTH_USER_MODEL, null=True, blank=True, on_delete=models.SET_NULL,\n        verbose_name="Uzytkownik"\n    )\n    action = models.CharField(max_length=20, choices=ACTION_CHOICES, verbose_name="Akcja")\n    target_type = models.CharField(max_length=10, choices=TARGET_CHOICES, verbose_name="Typ obiektu")\n    target_id = models.IntegerField(null=True, blank=True, verbose_name="ID obiektu")\n    target_repr = models.CharField(max_length=200, verbose_name="Obiekt (nazwa w momencie akcji)")\n    description = models.TextField(blank=True, verbose_name="Opis zmiany")\n\n    class Meta:\n        ordering = [\'-timestamp\']\n        verbose_name = "Wpis dziennika zmian"\n        verbose_name_plural = "Dziennik zmian"\n\n    def __str__(self):\n        return f"{self.get_action_display()} - {self.target_repr}"\n'
FILES['clients/forms.py'] = 'import re\nfrom datetime import date\nfrom django import forms\nfrom django.core.exceptions import ValidationError\nfrom .models import Owner, Dog\n\nMAX_PHOTO_SIZE_MB = 5\n\n\nclass OwnerForm(forms.ModelForm):\n    class Meta:\n        model = Owner\n        fields = [\n            \'first_name\', \'last_name\', \'phone\', \'email\', \'address\', \'notes\',\n            \'secondary_contact_name\', \'secondary_contact_phone\',\n            \'rodo_consent\', \'photo_consent\',\n        ]\n        widgets = {\n            \'first_name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'Imie\'}),\n            \'last_name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'Nazwisko\'}),\n            \'phone\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. 600 123 456\'}),\n            \'email\': forms.EmailInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. jan@example.com\'}),\n            \'address\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. ul. Kwiatowa 5, Warszawa\'}),\n            \'notes\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 3, \'placeholder\': \'Notatki, np. preferowany kontakt...\'}),\n            \'secondary_contact_name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. partner/partnerka, dziecko\'}),\n            \'secondary_contact_phone\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. 600 999 888\'}),\n            \'rodo_consent\': forms.CheckboxInput(attrs={\'class\': \'form-check-input\'}),\n            \'photo_consent\': forms.CheckboxInput(attrs={\'class\': \'form-check-input\'}),\n        }\n\n    def clean_first_name(self):\n        value = self.cleaned_data.get(\'first_name\', \'\').strip()\n        if len(value) < 2:\n            raise ValidationError(\'Imie musi miec przynajmniej 2 znaki.\')\n        return value\n\n    def clean_last_name(self):\n        value = self.cleaned_data.get(\'last_name\', \'\').strip()\n        if len(value) < 2:\n            raise ValidationError(\'Nazwisko musi miec przynajmniej 2 znaki.\')\n        return value\n\n    def is_phone_suspicious(self):\n        phone = self.cleaned_data.get(\'phone\', \'\')\n        digits_only = re.sub(r\'\\D\', \'\', phone or \'\')\n        return len(digits_only) not in (9, 11, 12)\n\n    def is_phone_duplicate(self):\n        """NIEBLOKUJACA walidacja - sprawdza czy inny (aktywny) wlasciciel\n        juz ma ten sam numer telefonu. Zwraca znaleziony Owner lub None."""\n        phone = self.cleaned_data.get(\'phone\', \'\')\n        if not phone:\n            return None\n        qs = Owner.objects.filter(phone=phone, is_active=True)\n        if self.instance and self.instance.pk:\n            qs = qs.exclude(pk=self.instance.pk)\n        return qs.first()\n\n\nclass DogForm(forms.ModelForm):\n    class Meta:\n        model = Dog\n        fields = [\n            \'owner\', \'name\', \'breed\', \'sex\', \'birth_date\', \'weight_kg\',\n            \'health_notes\', \'health_tags\', \'trainer_notes\', \'photo\', \'training_status\',\n        ]\n        widgets = {\n            \'owner\': forms.Select(attrs={\'class\': \'form-select\'}),\n            \'name\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'Imie psa\'}),\n            \'breed\': forms.TextInput(attrs={\'class\': \'form-control\', \'placeholder\': \'np. Border Collie\'}),\n            \'sex\': forms.Select(attrs={\'class\': \'form-select\'}),\n            \'birth_date\': forms.DateInput(attrs={\'class\': \'form-control\', \'type\': \'date\'}),\n            \'weight_kg\': forms.NumberInput(attrs={\'class\': \'form-control\', \'step\': \'0.1\', \'placeholder\': \'np. 22.5\'}),\n            \'health_notes\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 3, \'placeholder\': \'Kontuzje, przeciwwskazania...\'}),\n            \'health_tags\': forms.CheckboxSelectMultiple(),\n            \'trainer_notes\': forms.Textarea(attrs={\'class\': \'form-control\', \'rows\': 3, \'placeholder\': \'Prywatne notatki trenera...\'}),\n            \'photo\': forms.ClearableFileInput(attrs={\'class\': \'form-control\'}),\n            \'training_status\': forms.Select(attrs={\'class\': \'form-select\'}),\n        }\n\n    def __init__(self, *args, fixed_owner=None, **kwargs):\n        super().__init__(*args, **kwargs)\n        self.fields[\'owner\'].queryset = Owner.objects.filter(is_active=True)\n        if fixed_owner is not None:\n            self.fields[\'owner\'].initial = fixed_owner.pk\n            self.fields[\'owner\'].widget = forms.HiddenInput()\n            self.fields[\'owner\'].required = False\n        self.fields[\'health_tags\'].required = False\n\n    def clean_name(self):\n        value = self.cleaned_data.get(\'name\', \'\').strip()\n        if len(value) < 2:\n            raise ValidationError(\'Imie psa musi miec przynajmniej 2 znaki.\')\n        return value\n\n    def clean_birth_date(self):\n        """BLOKUJACA walidacja - data urodzenia psa nie moze byc z przyszlosci."""\n        value = self.cleaned_data.get(\'birth_date\')\n        if value and value > date.today():\n            raise ValidationError(\'Data urodzenia nie moze byc z przyszlosci.\')\n        return value\n\n    def clean_photo(self):\n        photo = self.cleaned_data.get(\'photo\')\n        if photo and hasattr(photo, \'size\'):\n            if photo.size > MAX_PHOTO_SIZE_MB * 1024 * 1024:\n                raise ValidationError(f\'Zdjecie jest za duze (max {MAX_PHOTO_SIZE_MB}MB).\')\n            content_type = getattr(photo, \'content_type\', None)\n            if content_type and not content_type.startswith(\'image/\'):\n                raise ValidationError(\'Plik musi byc obrazem.\')\n        return photo\n'
FILES['clients/templates/clients/dog_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }}</h1>\n{% if fixed_owner %}\n<p class="text-muted">Wlasciciel: <strong>{{ fixed_owner.full_name }}</strong></p>\n{% endif %}\n\n<div class="form-card">\n    <form method="post" enctype="multipart/form-data">\n        {% csrf_token %}\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        {% if not fixed_owner %}\n        <div class="mb-3">\n            <label class="form-label">Wlasciciel</label>\n            {{ form.owner }}\n            {% if form.owner.errors %}<div class="invalid-feedback-custom">{{ form.owner.errors|first }}</div>{% endif %}\n        </div>\n        {% else %}\n            {{ form.owner }}\n        {% endif %}\n\n        <div class="mb-3">\n            <label class="form-label">Imie psa</label>\n            {{ form.name }}\n            {% if form.name.errors %}<div class="invalid-feedback-custom">{{ form.name.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="row">\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Rasa (opcjonalnie)</label>\n                {{ form.breed }}\n            </div>\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Plec (opcjonalnie)</label>\n                {{ form.sex }}\n            </div>\n        </div>\n\n        <div class="row">\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Data urodzenia (opcjonalnie)</label>\n                {{ form.birth_date }}\n                {% if form.birth_date.errors %}<div class="invalid-feedback-custom">{{ form.birth_date.errors|first }}</div>{% endif %}\n            </div>\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Waga w kg (opcjonalnie)</label>\n                {{ form.weight_kg }}\n            </div>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Status treningowy</label>\n            {{ form.training_status }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Informacje zdrowotne / przeciwwskazania (opis slowny)</label>\n            {{ form.health_notes }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label"><i class="bi bi-tags"></i> Tagi zdrowotne (przeciwwskazania)</label>\n            <div class="checkbox-group">\n                {{ form.health_tags }}\n            </div>\n            <small class="text-muted">\n                Uzywane do automatycznych ostrzezen - jesli dodasz do planu cwiczenie z tym samym tagiem,\n                zobaczysz ostrzezenie.\n            </small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Notatki trenera</label>\n            {{ form.trainer_notes }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label"><i class="bi bi-image"></i> Zdjecie (opcjonalnie)</label>\n            {{ form.photo }}\n            {% if form.photo.errors %}<div class="invalid-feedback-custom">{{ form.photo.errors|first }}</div>{% endif %}\n            {% if dog and dog.photo %}\n                <div class="mt-2">\n                    <img src="{{ dog.photo.url }}" style="max-width:150px;border-radius:10px;" alt="{{ dog.name }}">\n                </div>\n            {% endif %}\n        </div>\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            {% if fixed_owner %}\n                <a href="{% url \'owner_detail\' fixed_owner.pk %}" class="btn btn-secondary">Anuluj</a>\n            {% else %}\n                <a href="{% url \'dog_list\' %}" class="btn btn-secondary">Anuluj</a>\n            {% endif %}\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/dog_detail.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ dog.name }}{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-suit-heart-fill"></i> {{ dog.name }}\n        {% if dog.training_status == \'paused\' %}\n            <span class="badge bg-warning text-dark">Trening wstrzymany</span>\n        {% endif %}\n    </h1>\n    <div>\n        <a href="{% url \'dog_pdf\' dog.pk %}" target="_blank" class="btn btn-outline-secondary">\n            <i class="bi bi-file-pdf"></i> Karta PDF\n        </a>\n        <form method="post" action="{% url \'dog_toggle_training_status\' dog.pk %}" style="display:inline;">\n            {% csrf_token %}\n            {% if dog.training_status == \'paused\' %}\n                <button type="submit" class="btn btn-outline-success">\n                    <i class="bi bi-play-circle"></i> Przywroc trening\n                </button>\n            {% else %}\n                <button type="submit" class="btn btn-outline-warning">\n                    <i class="bi bi-pause-circle"></i> Wstrzymaj trening\n                </button>\n            {% endif %}\n        </form>\n        <a href="{% url \'dog_update\' dog.pk %}" class="btn btn-outline-secondary">\n            <i class="bi bi-pencil"></i> Edytuj\n        </a>\n        <a href="{% url \'dog_delete\' dog.pk %}" class="btn btn-outline-danger">\n            <i class="bi bi-archive"></i> Archiwizuj\n        </a>\n        <a href="{% url \'owner_detail\' dog.owner.pk %}" class="btn btn-secondary">\n            <i class="bi bi-arrow-left"></i> Powrot do wlasciciela\n        </a>\n    </div>\n</div>\n\n<div class="row">\n    <div class="col-md-4">\n        {% if dog.photo %}\n            <img src="{{ dog.photo.url }}" class="img-fluid rounded mb-3" alt="{{ dog.name }}">\n        {% else %}\n            <div class="card-img-placeholder mb-3" style="height:250px;"><i class="bi bi-image"></i></div>\n        {% endif %}\n    </div>\n    <div class="col-md-8">\n        <div class="detail-section">\n            <p><i class="bi bi-person"></i> Wlasciciel: <a href="{% url \'owner_detail\' dog.owner.pk %}">{{ dog.owner.full_name }}</a>\n                (<a href="tel:{{ dog.owner.phone }}">{{ dog.owner.phone }}</a>)\n            </p>\n            {% if dog.breed %}<p><i class="bi bi-tag"></i> Rasa: {{ dog.breed }}</p>{% endif %}\n            {% if dog.get_sex_display %}<p><i class="bi bi-gender-ambiguous"></i> Plec: {{ dog.get_sex_display }}</p>{% endif %}\n            {% if dog.get_age_display %}<p><i class="bi bi-cake2"></i> Wiek: {{ dog.get_age_display }}</p>{% endif %}\n            {% if dog.weight_kg %}<p><i class="bi bi-speedometer2"></i> Waga: {{ dog.weight_kg }} kg</p>{% endif %}\n\n            {% if dog.health_tags.all %}\n                <div class="mb-2">\n                    <strong class="small text-muted"><i class="bi bi-tags"></i> Tagi zdrowotne:</strong><br>\n                    {% for tag in dog.health_tags.all %}\n                        <span class="badge bg-warning text-dark">{{ tag.name }}</span>\n                    {% endfor %}\n                </div>\n            {% endif %}\n\n            {% if dog.health_notes %}\n                <div class="alert alert-warning mt-3">\n                    <i class="bi bi-exclamation-triangle-fill"></i>\n                    <strong>Informacje zdrowotne:</strong> {{ dog.health_notes|linebreaks }}\n                </div>\n            {% endif %}\n\n            {% if dog.trainer_notes %}\n                <hr>\n                <h6>Notatki trenera</h6>\n                <p>{{ dog.trainer_notes|linebreaks }}</p>\n            {% endif %}\n        </div>\n    </div>\n</div>\n{% endblock %}\n'
FILES['clients/admin.py'] = 'from django.contrib import admin\nfrom .models import Owner, Dog, AuditLog\n\n\nclass DogInline(admin.TabularInline):\n    model = Dog\n    extra = 1\n    fields = (\'name\', \'breed\', \'sex\', \'birth_date\', \'weight_kg\', \'training_status\', \'is_active\')\n\n\n@admin.register(Owner)\nclass OwnerAdmin(admin.ModelAdmin):\n    list_display = (\'full_name\', \'phone\', \'email\', \'address\', \'rodo_consent\', \'is_active\', \'created_at\')\n    list_filter = (\'is_active\', \'rodo_consent\', \'photo_consent\')\n    search_fields = (\'first_name\', \'last_name\', \'phone\', \'email\', \'address\')\n    inlines = [DogInline]\n    actions = [\'make_active\', \'make_archived\']\n\n    def make_active(self, request, queryset):\n        updated = queryset.update(is_active=True)\n        self.message_user(request, f"Przywrocono {updated} wlascicieli.")\n    make_active.short_description = "Przywroc zaznaczonych"\n\n    def make_archived(self, request, queryset):\n        updated = queryset.update(is_active=False)\n        self.message_user(request, f"Zarchiwizowano {updated} wlascicieli.")\n    make_archived.short_description = "Zarchiwizuj zaznaczonych"\n\n\n@admin.register(Dog)\nclass DogAdmin(admin.ModelAdmin):\n    list_display = (\'name\', \'owner\', \'breed\', \'sex\', \'training_status\', \'is_active\', \'created_at\')\n    list_filter = (\'is_active\', \'training_status\', \'sex\', \'breed\', \'health_tags\')\n    search_fields = (\'name\', \'breed\', \'owner__first_name\', \'owner__last_name\')\n    filter_horizontal = (\'health_tags\',)\n\n\n@admin.register(AuditLog)\nclass AuditLogAdmin(admin.ModelAdmin):\n    list_display = (\'timestamp\', \'user\', \'action\', \'target_type\', \'target_repr\')\n    list_filter = (\'action\', \'target_type\')\n    search_fields = (\'target_repr\', \'description\', \'user__username\')\n    readonly_fields = (\'timestamp\', \'user\', \'action\', \'target_type\', \'target_id\', \'target_repr\', \'description\')\n\n    def has_add_permission(self, request):\n        return False\n\n    def has_change_permission(self, request, obj=None):\n        return False\n'
